import {readFileSync,existsSync} from "node:fs";
import {resolve,dirname} from "node:path";
import {createHash} from "node:crypto";
import assert from "node:assert/strict";
const sha=x=>createHash("sha256").update(x).digest("hex");
const files=["docs/reviews/system-software-evidence-c253dda.md","docs/current.md"];
let links=0;
for(const file of files) {
 const text=readFileSync(file,"utf8");
 for(const match of text.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)) {
  const target=match[1];
  if(/^(https?:|#)/.test(target)) continue;
  assert(existsSync(resolve(dirname(file),target.split("#")[0])),file+": "+target); links++;
 }
}
const inventory=JSON.parse(readFileSync("docs/reviews/system-software-evidence-c253dda/u1-inventory.json"));
const build=JSON.parse(readFileSync("docs/reviews/system-software-evidence-c253dda/u1-build.json"));
assert.equal(build.checkout_sha,inventory.commands[0].stdout.trim());
assert.equal(build.host.exit_code,0); assert.equal(build.guest.exit_code,0);
assert.deepEqual(build.source_changes_since_inventory,[]);
for(const a of inventory.sources) assert.equal(sha(readFileSync(a.path)),a.sha256,a.path);
for(const a of build.assets) {assert(a.present,a.path);assert.equal(sha(readFileSync(a.path)),a.sha256,a.path);}
assert.equal(sha(JSON.stringify(inventory.sources)),inventory.source_manifest_sha256);
const patch=inventory.commands.find(c=>c.argv[1]==="diff"&&c.argv[2]==="--binary").stdout;
assert.equal(sha(patch),inventory.dirty_patch_sha256);
console.log(JSON.stringify({argv:[process.execPath,...process.execArgv],cwd:process.cwd(),exit_code:0,result:"PASS",relative_links_checked:links,source_hashes_checked:inventory.sources.length,asset_hashes_checked:build.assets.length,remote_links:"not checked",product_tests:"not run"},null,2));
